function CatHouseProbabilityUpDialog:Init()
    UIEventProxy.Create(self.EventReceiver.gameObject).onPointerClick = function()
        UIModule.CloseDialog(self.controller)
    end
end

function CatHouseProbabilityUpDialog:SetPanelInfo()
    self.TxtTitle.text = localize("本期限时概率提升!")
    self:SetTimerAction()
    self:SetCatData()
    self:SetGenesDataList()
    self:SetComponentDataList()
end

function CatHouseProbabilityUpDialog:SetTimerAction()
    local timer = CatHouseMgr:GetInstance().timerGeneRateUp
    if not IsNull(timer) then
        self:SetTimerTxt(localize("活动剩余时间:_time_", {_time_ = CfUtils.GetTimeHMS(timer.CountTimes)}))
        self.__EventGeneRateUpCDChange = Events.AddListener(CatHouseGeneRateUpCDChange, function (count)
            if count <= 0 then   -- 结束
                self:SetTimerTxt(localize("活动已结束"))
            else
                self:SetTimerTxt(localize("活动剩余时间:_time_", {_time_ = CfUtils.GetTimeHMS(count)}))
            end
        end)
        -- timer.OnCd = function(count)
        --     if count <= 0 then   -- 结束
        --         CatHouseMgr:GetInstance():CleanTimerGeneRateUp()
        --         self:SetTimerTxt(localize("活动已结束"))
        --     else
        --         self:SetTimerTxt(localize("活动剩余时间:_time_", {_time_ = CfUtils.GetTimeHMS(count)}))
        --     end
        -- end
    end
end

function CatHouseProbabilityUpDialog:SetTimerTxt(value)
    if not isNull(self.TxtRemain) then
        self.TxtRemain.text = value
    end
end

function CatHouseProbabilityUpDialog:SetCatData()
    xTry(function() 
        local pathStrings = string.split2(self.picture, ":")
        local path = CS.GameUtils.GetCombineResourceDirPath(checkInt(pathStrings[1]), pathStrings[2], ".png")
        self.RImgCat:LoadSprite(path)
        self.RImgIcon:LoadSprite(checkString(self.catDataVo.icon))
        self.TxtCatName.text = checkString(self.catDataVo.name)
    end)
end

function CatHouseProbabilityUpDialog:SetGenesDataList()
    KTool.SetActive(self.OtherData.gameObject, not isNull(self.listBasicGenes))
    if isNull(self.listBasicGenes) then return end
    for i, geneId in ipairs(self.listBasicGenes) do
        local data = {}
        data.geneId = checkNumber(geneId)
        local goNode = KTool.Instantiate(self.OtherDataNodesFather.gameObject, self.OtherDataNode.gameObject)
        local nodeEnv = CfUtils.GetLuaScr(goNode, "Game.CatHouse.Interaction.CatHouseDataNode")
        nodeEnv:FreshAdult(data, {})
        nodeEnv:SetBtnCallBack(function() 
            CatHouseMgr:GetInstance():ShowCatHousDataDetailsNode(goNode, data) 
        end)
        KTool.SetActive(goNode, true)
    end
end

function CatHouseProbabilityUpDialog:SetComponentDataList()
    KTool.SetActive(self.PartData.gameObject, not isNull(self.listComponentGenes))
    if isNull(self.listComponentGenes) then return end

    local catSkillIdList
    if self.catDataVo then
        catSkillIdList = self.catDataVo.catSkillIdList
    end

    for i, geneId in ipairs(self.listComponentGenes) do
        local data = {}
        data.geneId = checkNumber(geneId)
        local geneVo = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", geneId)
        data.skillId = checkNumber(geneVo.catSkillIdList[1])
        local goNode = KTool.Instantiate(self.PartDataNodesFather.gameObject, self.PartDataNode.gameObject)
        data.geneId = checkNumber(geneId)
        local nodeEnv = CfUtils.GetLuaScr(goNode, "Game.CatHouse.Interaction.CatHouseDataNode")
        nodeEnv:FreshAdult(data, {})
        nodeEnv:SetBtnCallBack(function()
            CatHouseMgr:GetInstance():ShowCatHousDataDetailsNode(goNode, data)
        end)
        KTool.SetActive(goNode, true)
    end
end

return CatHouseProbabilityUpDialog
